// buildReq builds a BuildRequestRequest from a fixture query struct — the
// MatchResult.query the core passes through verbatim. No I/O — the whole
// shaping is a pure function of this struct.
func buildReq(t *testing.T, query map[string]any) *metadatav1.BuildRequestRequest {
	t.Helper()
	q, err := structpb.NewStruct(query)
	if err != nil {
		t.Fatalf("fixture query struct: %v", err)
	}
	return &metadatav1.BuildRequestRequest{Query: q}
}

// planSpecs flattens a BuildRequestResponse into [primary, extras...] — the
// ordered request plan the core executes.
func planSpecs(res *metadatav1.BuildRequestResponse) []*metadatav1.RequestSpec {
	out := []*metadatav1.RequestSpec{res.GetSpec()}
	return append(out, res.GetExtraSpecs()...)
}

// requireSpecContract pins the SERVER request contract on one spec (the box
// 1.3 law): GET, the 250 ms pacing, the RU-first language variable, and the
// api key riding SOLELY as the redacted_ref scoped server:api_key — its
// placeholder is in the template and its variable is a redacted_ref, never a
// literal value.
func requireSpecContract(t *testing.T, name string, s *metadatav1.RequestSpec) {
	t.Helper()
	if got := s.GetMethod(); got != "GET" {
		t.Errorf("%s: method = %q, want GET", name, got)
	}
	if got := s.GetMinIntervalMs(); got != minIntervalMS {
		t.Errorf("%s: min_interval_ms = %d, want %d", name, got, minIntervalMS)
	}
	if got := s.GetVariables()[languageVar].GetStringValue(); got != languageRU {
		t.Errorf("%s: language variable = %q, want %q", name, got, languageRU)
	}
	if got := s.GetVariables()[apiKeyVar].GetRedactedRef(); got != apiKeyRef {
		t.Errorf("%s: api_key variable = %q, want the redacted_ref %q", name, got, apiKeyRef)
	}
	if !strings.Contains(s.GetUrlTemplate(), "api_key={api_key}") {
		t.Errorf("%s: url template %q carries no {api_key} placeholder", name, s.GetUrlTemplate())
	}
	if !strings.Contains(s.GetUrlTemplate(), "language={language}") {
		t.Errorf("%s: url template %q carries no {language} placeholder", name, s.GetUrlTemplate())
	}
}

// TestBuildRequestSearchSpecs pins the search plans (box 1.3): a film query
// builds the movie search carrying the title and the parsed year — the year
// filter joins only when the query carries one — and a series query builds
// the tv search on the title alone (the season rides the query for
// disambiguation, never into the URL). Every search plan is single-fetch:
// no extra specs.
func TestBuildRequestSearchSpecs(t *testing.T) {
	p := &sourceImpl{}

	res, err := p.BuildRequest(context.Background(), buildReq(t,
		map[string]any{"title": "Perfect Blue", "year": int64(1997)}))
	if err != nil {
		t.Fatalf("BuildRequest movie search: %v", err)
	}
	if res.GetSpec() == nil {
		t.Fatal("movie search built no spec")
	}
	if got, want := res.GetSpec().GetUrlTemplate(),
		defaultAPIBase+"/search/movie?query={title}&year={year}&language={language}&api_key={api_key}"; got != want {
		t.Errorf("movie search template = %q, want %q", got, want)
	}
	if got := res.GetSpec().GetVariables()[titleKey].GetStringValue(); got != "Perfect Blue" {
		t.Errorf("title variable = %q, want %q", got, "Perfect Blue")
	}
	if got := res.GetSpec().GetVariables()[yearKey].GetIntValue(); got != 1997 {
		t.Errorf("year variable = %d, want 1997", got)
	}
	if len(res.GetExtraSpecs()) != 0 {
		t.Errorf("movie search carried %d extras — a search plan must stay single-fetch", len(res.GetExtraSpecs()))
	}
	requireSpecContract(t, "movie search", res.GetSpec())

	// A film query with no parsed year: the movie search without the year
	// filter, and no dangling year variable.
	res, err = p.BuildRequest(context.Background(), buildReq(t,
		map[string]any{"title": "Perfect Blue"}))
	if err != nil {
		t.Fatalf("BuildRequest yearless movie search: %v", err)
	}
	if got, want := res.GetSpec().GetUrlTemplate(),
		defaultAPIBase+"/search/movie?query={title}&language={language}&api_key={api_key}"; got != want {
		t.Errorf("yearless movie search template = %q, want %q", got, want)
	}
	if _, has := res.GetSpec().GetVariables()[yearKey]; has {
		t.Error("yearless movie search declared a year variable its template never references")
	}

	res, err = p.BuildRequest(context.Background(), buildReq(t,
		map[string]any{"title": "Друзья", "season": int64(2)}))
	if err != nil {
		t.Fatalf("BuildRequest tv search: %v", err)
	}
	if got, want := res.GetSpec().GetUrlTemplate(),
		defaultAPIBase+"/search/tv?query={title}&language={language}&api_key={api_key}"; got != want {
		t.Errorf("tv search template = %q, want %q", got, want)
	}
	if got := res.GetSpec().GetVariables()[titleKey].GetStringValue(); got != "Друзья" {
		t.Errorf("title variable = %q, want %q", got, "Друзья")
	}
	if _, has := res.GetSpec().GetVariables()[seasonKey]; has {
		t.Error("tv search declared a season variable — the season disambiguates upstream-side, it never enters the URL")
	}
	if len(res.GetExtraSpecs()) != 0 {
		t.Errorf("tv search carried %d extras — a search plan must stay single-fetch", len(res.GetExtraSpecs()))
	}
	requireSpecContract(t, "tv search", res.GetSpec())
}

// TestBuildRequestAnchoredMoviePlanCarriesCreditsExtra pins the anchored film
// plan (box 1.3): an id-anchored query without a season resolves to the
// movie-detail primary with the credits fetch as the one extra spec, both
// anchored on the same tmdb_id.
func TestBuildRequestAnchoredMoviePlanCarriesCreditsExtra(t *testing.T) {
	p := &sourceImpl{}
	res, err := p.BuildRequest(context.Background(), buildReq(t, map[string]any{"tmdb_id": int64(123)}))
	if err != nil {
		t.Fatalf("BuildRequest anchored movie: %v", err)
	}
	if got, want := res.GetSpec().GetUrlTemplate(),
		defaultAPIBase+"/movie/{tmdb_id}?language={language}&api_key={api_key}"; got != want {
		t.Errorf("anchored movie template = %q, want %q", got, want)
	}
	if got := res.GetSpec().GetVariables()[idKey].GetIntValue(); got != 123 {
		t.Errorf("tmdb_id variable = %d, want 123", got)
	}
	if len(res.GetExtraSpecs()) != 1 {
		t.Fatalf("anchored movie plan carried %d extras, want exactly the credits fetch", len(res.GetExtraSpecs()))
	}
	credits := res.GetExtraSpecs()[0]
	if got, want := credits.GetUrlTemplate(),
		defaultAPIBase+"/movie/{tmdb_id}/credits?language={language}&api_key={api_key}"; got != want {
		t.Errorf("credits template = %q, want %q", got, want)
	}
	if got := credits.GetVariables()[idKey].GetIntValue(); got != 123 {
		t.Errorf("credits tmdb_id variable = %d, want 123", got)
	}
	requireSpecContract(t, "movie detail", res.GetSpec())
	requireSpecContract(t, "credits extra", credits)
}

// TestBuildRequestAnchoredSeriesPlanCarriesSeasonExtra pins the anchored
// series plan (box 1.3): an id-anchored query carrying season n resolves to
// the tv-detail primary with the season-n fetch as the one extra spec after
// it — n is the query's own season fact.
func TestBuildRequestAnchoredSeriesPlanCarriesSeasonExtra(t *testing.T) {
	p := &sourceImpl{}
	res, err := p.BuildRequest(context.Background(), buildReq(t,
		map[string]any{"tmdb_id": int64(456), "season": int64(2)}))
	if err != nil {
		t.Fatalf("BuildRequest anchored series: %v", err)
	}
	if got, want := res.GetSpec().GetUrlTemplate(),
		defaultAPIBase+"/tv/{tmdb_id}?language={language}&api_key={api_key}"; got != want {
		t.Errorf("anchored series template = %q, want %q", got, want)
	}
	if got := res.GetSpec().GetVariables()[idKey].GetIntValue(); got != 456 {
		t.Errorf("tmdb_id variable = %d, want 456", got)
	}
	if len(res.GetExtraSpecs()) != 1 {
		t.Fatalf("anchored series plan carried %d extras, want exactly the season fetch", len(res.GetExtraSpecs()))
	}
	season := res.GetExtraSpecs()[0]
	if got, want := season.GetUrlTemplate(),
		defaultAPIBase+"/tv/{tmdb_id}/season/{season}?language={language}&api_key={api_key}"; got != want {
		t.Errorf("season template = %q, want %q", got, want)
	}
	if got := season.GetVariables()[seasonKey].GetIntValue(); got != 2 {
		t.Errorf("season variable = %d, want 2 — n is the query's own season fact", got)
	}
	if got := season.GetVariables()[idKey].GetIntValue(); got != 456 {
		t.Errorf("season tmdb_id variable = %d, want 456", got)
	}
	requireSpecContract(t, "tv detail", res.GetSpec())
	requireSpecContract(t, "season extra", season)
}

// TestBuildRequestSecretRefRuLanguagePacing pins the contract EVERY tmdb
// spec carries, across every plan shape the plugin builds: the api key rides
// solely as the redacted_ref scoped server:api_key (never a literal — the
// placeholder substitutes from the resolved variable), the language is
// ru-RU, the pacing is 250 ms. Every spec's FULL composed URL template is
// pinned as a literal too — path and query joined by exactly one "?" — so a
// composition regression (the "&"-led suffix on a bare path the joint wire
// caught) cannot pass by prefix agreement. It also pins the upstream seam's
// branches: the env override replaces the base (trailing slash trimmed) and
// the fallback is the production default.
func TestBuildRequestSecretRefRuLanguagePacing(t *testing.T) {
	p := &sourceImpl{}
	shapes := []struct {
		name     string
		query    map[string]any
		wantURL  string // the primary spec's full URL template
		extraURL string // the extra spec's full URL template; "" = single-fetch
	}{
		{"movie search", map[string]any{"title": "Perfect Blue", "year": int64(1997)},
			defaultAPIBase + "/search/movie?query={title}&year={year}&language={language}&api_key={api_key}", ""},
		{"tv search", map[string]any{"title": "Друзья", "season": int64(2)},
			defaultAPIBase + "/search/tv?query={title}&language={language}&api_key={api_key}", ""},
		{"anchored movie", map[string]any{"tmdb_id": int64(123)},
			defaultAPIBase + "/movie/{tmdb_id}?language={language}&api_key={api_key}",
			defaultAPIBase + "/movie/{tmdb_id}/credits?language={language}&api_key={api_key}"},
		{"anchored series", map[string]any{"tmdb_id": int64(456), "season": int64(2)},
			defaultAPIBase + "/tv/{tmdb_id}?language={language}&api_key={api_key}",
			defaultAPIBase + "/tv/{tmdb_id}/season/{season}?language={language}&api_key={api_key}"},
	}
	for _, shape := range shapes {
		res, err := p.BuildRequest(context.Background(), buildReq(t, shape.query))
		if err != nil {
			t.Fatalf("BuildRequest %s: %v", shape.name, err)
		}
		if got, want := res.GetSpec().GetUrlTemplate(), shape.wantURL; got != want {
			t.Errorf("%s primary url template = %q, want %q", shape.name, got, want)
		}
		if shape.extraURL == "" {
			if len(res.GetExtraSpecs()) != 0 {
				t.Errorf("%s carried %d extras — its plan is single-fetch", shape.name, len(res.GetExtraSpecs()))
			}
		} else {
			if len(res.GetExtraSpecs()) != 1 {
				t.Fatalf("%s carried %d extras, want exactly one", shape.name, len(res.GetExtraSpecs()))
			}
			if got, want := res.GetExtraSpecs()[0].GetUrlTemplate(), shape.extraURL; got != want {
				t.Errorf("%s extra url template = %q, want %q", shape.name, got, want)
			}
		}
		for _, spec := range planSpecs(res) {
			requireSpecContract(t, shape.name+" spec", spec)
		}
	}

	// The seam (the joint tests' stub point): the override wins with
	// trailing slashes trimmed; without it the production default stands.
	t.Setenv(upstreamEnvVar, "http://127.0.0.1:1/tmdb///")
	if got, want := upstreamBase(), "http://127.0.0.1:1/tmdb"; got != want {
		t.Errorf("upstreamBase override = %q, want %q (trailing slashes trimmed)", got, want)
	}
	t.Setenv(upstreamEnvVar, "")
	if got := upstreamBase(); got != defaultAPIBase {
		t.Errorf("upstreamBase fallback = %q, want the default %q", got, defaultAPIBase)
	}
}
